// A 3D reduction
affine example_3d_max [N]->{ : 0<N }
inputs 
  X : {[k] : 0<=k<=N}
outputs
  Y : {[i,j] : j>=N-i and j>=2i-2N and 2j<=2N+i}
let
  Y[i,j] = reduce(max, [k], {: 0<=k<=2N-2i+j and k<=2N+i-2j and k<=i+j-N} : X[k]);
.

// A 3D reduction
affine example_3d_sum [N]->{ : 0<N }
inputs 
  X : {[k] : 0<=k<=N}
outputs
  Y : {[i,j] : j>=N-i and j>=2i-2N and 2j<=2N+i}
let
  Y[i,j] = reduce(+, [k], {: 0<=k<=2N-2i+j and k<=2N+i-2j and k<=i+j-N} : X[k]);
.

// A reduction with a 4-dimensional body, 2-dimensional accumulation and 2-dimensional reuse
affine example_4d [N]->{ : 10<N }
inputs 
  X : {[i,j] : 0<=i<=j<2N}
outputs
  Y : {[i,j] : 0<=i<=j<N}
let
  Y[i,j] = reduce(max, [k,l], {: i<=k<=2i and i+j<=l<=2j} : X[k,l]);
.

// Sliding and increasing max filter (Section 2.3)
affine increasing_max_filter [N]->{:0<N}
inputs
  X : {[i] : 0<=i<=2N}
outputs
  Y : {[i] : 0<=i<=N}
let
  Y[i] = reduce(max, [j], {: i<=j<=2i} : X[j]);
.

// Simple prefix max (Section 2.2)
affine prefix_max [N]->{:0<N}
inputs
  X : {[i] : 0<=i<=N}
outputs
  Y : {[i] : 0<=i<=N}
let
  Y[i] = reduce(max, [j], {: 0<=j<=i} : X[j]);
.

// Simple prefix sum (Section 2.1)
affine prefix_sum [N]->{:0<N}
inputs
  X : {[i] : 0<=i<=N}
outputs
  Y : {[i] : 0<=i<=N}
let
  Y[i] = reduce(+, [j], {: 0<=j<=i} : X[j]);
.

// The 3D working example (Section 3.3)
affine working_example [N]->{ : 0<N }
inputs 
  X : {[k] : 0<=k<=N}
outputs
  Y : {[i] : 0<=i<=N}
let
  Y[i] = reduce(+, [j,k], {: i<=N and 0<=j and 0<=k and k<=i-j} : X[k]);
.

affine prefix_polynomial [N]->{:0<N}
inputs
 X : {[i] : 0<=i<=N}
outputs
 Y : {[i] : 0<=i<=N}
let
 Y[i] = reduce(+, [j], {: 0<=j<=i} : X[j]*X[j]+3*X[j]);
.

affine pair_prefix_product [N]->{:0<N}
inputs
 X : {[i] : 0<=i<=N}
outputs
 Y : {[i] : 0<=i<=N}
let
 Y[i] = reduce(+, [j,k], {: 0<=j<k<=i} : X[j]*X[k]);
.

affine variable_denominator [N]->{:0<N}
inputs
 X : {[i] : 0<=i<=N}
outputs
 Y : {[i] : 0<=i<=N}
let
 Y[i] = reduce(+, [j], {: 0<=j<=i} : 1/X[j]);
.
